text:
{
  "design": {
    "theme": "studio",
    "picture_style": "photo"
  },
  "flow": [
    {
      "slide": 1,
      "does": "Recall gas tests and evidence of reaction",
      "look_at": {"kind": "picture", "shows": "Magnesium bubbling in acid"},
      "teaches": []
    },
    {
      "slide": 2,
      "does": "Introduce the approved objectives",
      "look_at": {"kind": "none", "shows": null},
      "teaches": []
    },
    {
      "slide": 3,
      "does": "Teach how to collect and measure gas",
      "look_at": {"kind": "diagram", "shows": "A sealed flask connected to a gas syringe"},
      "teaches": [2]
    },
    {
      "slide": 4,
      "does": "Teach a fair concentration investigation",
      "look_at": {"kind": "none", "shows": null},
      "teaches": [2]
    },
    {
      "slide": 5,
      "does": "Model a mean-rate calculation",
      "look_at": {"kind": "diagram", "shows": "Gas volume measured at two times"},
      "teaches": [1]
    },
    {
      "slide": 6,
      "does": "Check a matched calculation and interpretation",
      "look_at": {"kind": "none", "shows": null},
      "teaches": [1]
    },
    {
      "slide": 7,
      "does": "Predict the effect of concentration",
      "look_at": {"kind": "none", "shows": null},
      "teaches": [3]
    },
    {
      "slide": 8,
      "does": "Explain concentration using collision theory",
      "look_at": {"kind": "diagram", "shows": "More acid particles in the same volume near magnesium"},
      "teaches": [3]
    },
    {
      "slide": 9,
      "does": "Correct the belief that concentration makes particles faster",
      "look_at": {"kind": "diagram", "shows": "Different particle numbers but the same speed distribution"},
      "teaches": [3]
    },
    {
      "slide": 10,
      "does": "Check investigation planning and evaluation",
      "look_at": {"kind": "none", "shows": null},
      "teaches": [2]
    },
    {
      "slide": 11,
      "does": "Apply rate ideas to unfamiliar results",
      "look_at": {"kind": "diagram", "shows": "Two gas-volume curves with equal final volumes"},
      "teaches": [1, 3]
    },
    {
      "slide": 12,
      "does": "Apply all three objectives to a flawed investigation",
      "look_at": {"kind": "none", "shows": null},
      "teaches": [1, 2, 3]
    }
  ],
  "title": {
    "template": "title",
    "heading": "Rates of reaction",
    "lead": "Recall: what do bubbles show, and how would you test for hydrogen?",
    "picture": {
      "shows": "Magnesium ribbon reacting with dilute hydrochloric acid in a flask",
      "must_see": ["magnesium ribbon", "bubbles around ribbon", "clear acid solution"],
      "subject": "generic"
    }
  },
  "slides": [
    {
      "template": "visual-text",
      "heading": "Measure the gas produced",
      "lead": "Magnesium + hydrochloric acid → magnesium chloride + hydrogen",
      "points": [
        {"label": "Measurement", "text": "Read hydrogen volume in cm³ on the gas syringe."},
        {"label": "Timing", "text": "Record volume at regular time intervals."}
      ],
      "figure": {
        "kind": "labelled-diagram",
        "shows": "A conical flask containing dilute hydrochloric acid and magnesium ribbon, sealed with a bung and connected by a delivery tube to a horizontally clamped gas syringe. The syringe scale measures volume in cm³.",
        "labels": ["Gas syringe", "Volume scale (cm³)", "Clamp", "Delivery tube", "Bung", "Hydrochloric acid", "Magnesium ribbon"]
      }
    },
    {
      "template": "steps",
      "heading": "Investigate concentration fairly",
      "points": [
        "Wear goggles. Measure 25 cm³ of dilute hydrochloric acid into the flask.",
        "Add 0.020 g of magnesium ribbon. Fit the bung promptly and start timing.",
        "Record gas volume every 10 s until it stops increasing.",
        "Repeat with different acid concentrations; keep acid volume, magnesium mass and temperature constant.",
        "Use equal-sized, cleaned ribbon pieces. Repeat each concentration three times and calculate means."
      ],
      "figure": null
    },
    {
      "template": "equation-hero",
      "heading": "Worked example: mean rate",
      "lead": "Calculate the mean rate over the first 40 s.",
      "formula": "Mean rate = Δvolume ÷ Δtime",
      "points": [
        "Δvolume = 32 − 0 = 32 cm³",
        "Δtime = 40 − 0 = 40 s",
        "Mean rate = 32 ÷ 40 = 0.80 cm³/s"
      ],
      "figure": {
        "kind": "table",
        "shows": "The gas volumes needed to calculate mean rate over the first 40 seconds",
        "alt": "At zero seconds the gas volume is zero; at 40 seconds it is 32 cubic centimetres.",
        "title": null,
        "header": ["Time (s)", "Gas (cm³)"],
        "rows": [["0", "0"], ["40", "32"]]
      }
    },
    {
      "template": "practice",
      "heading": "Calculate mean rates",
      "questions": [
        "Gas volume rises from 0 to 36 cm³ in 40 s. Calculate the mean rate.",
        "Gas volume rises from 12 cm³ at 10 s to 30 cm³ at 30 s. Calculate the mean rate over this interval.",
        "A reaction has a mean rate of 0.50 cm³/s over its first 20 s. How much gas forms in that time?"
      ],
      "instruction": "Write your calculation and unit.",
      "picture": null
    },
    {
      "template": "hinge",
      "heading": "Predict the effect",
      "stem": "Acid concentration doubles at the same temperature. What happens initially?",
      "options": [
        "The rate increases: successful collisions occur more often.",
        "The rate increases: every particle moves faster.",
        "The rate stays the same: magnesium mass is unchanged.",
        "The rate decreases: acid particles block each other."
      ],
      "correct": 1
    },
    {
      "template": "visual-text",
      "heading": "Why does concentration affect rate?",
      "lead": "Higher concentration means more acid particles in the same volume.",
      "points": [
        "More particles collide with the magnesium each second.",
        "A successful collision has enough energy to react.",
        "More successful collisions each second mean a faster reaction."
      ],
      "figure": {
        "kind": "particles",
        "shows": "Two equal-volume panels at the same temperature, each with an identical magnesium surface along the bottom. The second contains twice as many acid-particle dots, with more dots approaching the surface. Use the same distribution of motion-arrow lengths in both panels.",
        "labels": ["Lower concentration", "Higher concentration", "Same temperature"]
      }
    },
    {
      "template": "visual-text",
      "heading": "More particles, not faster particles",
      "lead": "Doubling concentration does not double particle speed.",
      "points": [
        {"label": "Concentration", "text": "Adds particles per unit volume: more collisions each second."},
        {"label": "Temperature", "text": "Unchanged here: particles have the same average kinetic energy."}
      ],
      "figure": {
        "kind": "particles",
        "shows": "Two equal-volume panels at the same temperature. One contains six acid particles and the other twelve. Motion arrows show the same mix of short, medium and long arrows in each panel; the more concentrated panel has no systematically longer arrows.",
        "labels": ["0.5 mol/dm³", "1.0 mol/dm³", "Same temperature"]
      }
    },
    {
      "template": "practice",
      "heading": "Plan a reliable investigation",
      "questions": [
        "Compare 0.5 and 1.0 mol/dm³ hydrochloric acid using magnesium. Describe how to collect gas and record volume over time.",
        "State how you will control magnesium mass and temperature. Name two other conditions to keep the same.",
        "Explain why repeating each concentration three times is better than using one result."
      ],
      "instruction": "Write a method that another pupil could follow.",
      "picture": null
    },
    {
      "template": "big-visual",
      "heading": "Interpret two reactions",
      "lead": "Calculate each mean rate over 0–20 s. Explain why the curves differ but finish at the same volume.",
      "figure": {
        "kind": "line-graph",
        "shows": "Gas volume against time for equal masses of magnesium at the same temperature. Both acids are in excess; curve B represents the higher acid concentration.",
        "alt": "Curve A reaches 20 cubic centimetres at 20 seconds and plateaus at 40 by 80 seconds. B reaches 32 at 20 seconds and plateaus at 40 by 40 seconds.",
        "title": null,
        "x": {"label": "Time (s)", "min": 0, "max": 100, "step": 20},
        "y": {"label": "Gas volume (cm³)", "min": 0, "max": 40, "step": 10},
        "y2": null,
        "qualitative": false,
        "series": [
          {"label": "A", "points": [[0, 0], [20, 20], [40, 32], [60, 38], [80, 40], [100, 40]], "style": "line", "axis": "left"},
          {"label": "B", "points": [[0, 0], [20, 32], [40, 40], [60, 40], [80, 40], [100, 40]], "style": "line", "axis": "left"}
        ],
        "segments": null,
        "annotations": null,
        "intervals": null
      }
    },
    {
      "template": "practice",
      "heading": "Evaluate the evidence",
      "questions": [
        "Low-concentration acid gives 18 cm³ in 30 s; high-concentration acid gives 30 cm³ in 30 s. Both start at 0 cm³. Calculate both mean rates.",
        "The low-concentration trial used 0.020 g magnesium at 20°C; the high-concentration trial used 0.040 g at 30°C. Can concentration alone explain the results? Justify.",
        "Design a fair retest. Predict its rate trend and explain it using successful collisions.",
        "Optional Higher: a tangent to a gas-volume curve passes through (10 s, 18 cm³) and (30 s, 34 cm³). Estimate the instantaneous rate."
      ],
      "instruction": "Use the evidence, then improve the investigation.",
      "picture": null
    }
  ]
}
